func (a *MCPAdapter) toolSearchEnabled() bool {
	return a != nil && a.opts != nil && a.opts.ToolSearch != nil
}
func (a *MCPAdapter) toolSearchNames() (string, string) {
	searchName := "search_tools"
	callName := "call_tool"
	if a.toolSearchEnabled() {
		if a.opts.ToolSearch.SearchToolName != "" {
			searchName = a.opts.ToolSearch.SearchToolName
		}
		if a.opts.ToolSearch.CallToolName != "" {
			callName = a.opts.ToolSearch.CallToolName
		}
	}
	return searchName, callName
}
func (a *MCPAdapter) isToolSearchName(name string) bool {
	searchName, _ := a.toolSearchNames()
	return a.toolSearchEnabled() && name == searchName
}
func (a *MCPAdapter) isToolCallProxyName(name string) bool {
	_, callName := a.toolSearchNames()
	return a.toolSearchEnabled() && name == callName
}
func isGeneratedToolName(name string) bool {
	switch name {
	case "lookup":
		return true
	case "stream_chunks":
		return true
	case "wait_for_cancel":
		return true
	case "projected_lookup":
		return true
	default:
		return false
	}
}
func (a *MCPAdapter) isAlwaysVisibleToolName(name string) bool {
	if !a.toolSearchEnabled() {
		return true
	}
	for _, visible := range a.opts.ToolSearch.AlwaysVisible {
		if visible == name {
			return true
		}
	}
	return false
}
func validateToolSearchOptions(opts *MCPAdapterOptions) {
	if opts == nil || opts.ToolSearch == nil {
		return
	}
	searchName := "search_tools"
	callName := "call_tool"
	if opts.ToolSearch.SearchToolName != "" {
		searchName = opts.ToolSearch.SearchToolName
	}
	if opts.ToolSearch.CallToolName != "" {
		callName = opts.ToolSearch.CallToolName
	}
	if searchName == callName {
		panic(fmt.Sprintf("MCP ToolSearch synthetic tool names must be distinct: %q", searchName))
	}
	if opts.ToolSearch.MaxResults < 0 {
		panic("MCP ToolSearch MaxResults must be non-negative")
	}
	if opts.ToolSearch.MinScore < 0 {
		panic("MCP ToolSearch MinScore must be non-negative")
	}
	switch opts.ToolSearch.ExactMatchMode {
	case "", "narrow", "boost", "off":
	default:
		panic(fmt.Sprintf("MCP ToolSearch ExactMatchMode must be narrow, boost, or off: %q", opts.ToolSearch.ExactMatchMode))
	}
	if opts.ToolSearch.Weights != nil {
		weights := opts.ToolSearch.Weights
		if weights.Name < 0 || weights.Title < 0 || weights.Metadata < 0 || weights.Description < 0 || weights.Parameters < 0 || weights.FuzzyName < 0 {
			panic("MCP ToolSearch weights must be non-negative")
		}
	}
	if isGeneratedToolName(searchName) {
		panic(fmt.Sprintf("MCP ToolSearch search tool name %q collides with a generated tool", searchName))
	}
	if isGeneratedToolName(callName) {
		panic(fmt.Sprintf("MCP ToolSearch call tool name %q collides with a generated tool", callName))
	}
	for _, name := range opts.ToolSearch.AlwaysVisible {
		if name == "" {
			continue
		}
		if !isGeneratedToolName(name) {
			panic(fmt.Sprintf("MCP ToolSearch AlwaysVisible tool %q is not a generated tool", name))
		}
		if name == searchName || name == callName {
			panic(fmt.Sprintf("MCP ToolSearch AlwaysVisible tool %q collides with a synthetic tool", name))
		}
	}
}
func (a *MCPAdapter) toolSearchSettings() toolSearchSettings {
	settings := toolSearchSettings{
		broadFallback:     true,
		descriptionWeight: 250,
		exactMatchMode:    "narrow",
		fuzzyNameMatching: true,
		fuzzyNameWeight:   600,
		maxResults:        3,
		metadataWeight:    400,
		minScore:          0,
		nameWeight:        1000,
		parameterWeight:   100,
		titleWeight:       900,
	}
	if a.toolSearchEnabled() {
		opts := a.opts.ToolSearch
		if opts.MaxResults > 0 {
			settings.maxResults = opts.MaxResults
		}
		if opts.MinScore > 0 {
			settings.minScore = opts.MinScore
		}
		if opts.ExactMatchMode != "" {
			settings.exactMatchMode = opts.ExactMatchMode
		}
		if opts.FuzzyNameMatching != nil {
			settings.fuzzyNameMatching = *opts.FuzzyNameMatching
		}
		if opts.BroadFallback != nil {
			settings.broadFallback = *opts.BroadFallback
		}
		if opts.Weights != nil {
			if opts.Weights.Name > 0 {
				settings.nameWeight = opts.Weights.Name
			}
			if opts.Weights.Title > 0 {
				settings.titleWeight = opts.Weights.Title
			}
			if opts.Weights.Metadata > 0 {
				settings.metadataWeight = opts.Weights.Metadata
			}
			if opts.Weights.Description > 0 {
				settings.descriptionWeight = opts.Weights.Description
			}
			if opts.Weights.Parameters > 0 {
				settings.parameterWeight = opts.Weights.Parameters
			}
			if opts.Weights.FuzzyName > 0 {
				settings.fuzzyNameWeight = opts.Weights.FuzzyName
			}
		}
	}
	return settings
}
func (a *MCPAdapter) visibleToolCatalog(tools []*ToolInfo) []*ToolInfo {
	if !a.toolSearchEnabled() {
		return tools
	}
	pinned := make(map[string]struct{}, len(a.opts.ToolSearch.AlwaysVisible))
	for _, name := range a.opts.ToolSearch.AlwaysVisible {
		if name != "" {
			pinned[name] = struct{}{}
		}
	}
	visible := make([]*ToolInfo, 0, len(pinned)+2)
	for _, tool := range tools {
		if tool == nil {
			continue
		}
		if _, ok := pinned[tool.Name]; ok {
			visible = append(visible, tool)
		}
	}
	return visible
}
func (a *MCPAdapter) toolSearchSyntheticTools() []*ToolInfo {
	searchName, callName := a.toolSearchNames()
	return []*ToolInfo{toolSearchToolInfo(searchName), toolCallProxyToolInfo(callName)}
}
func toolSearchToolInfo(name string) *ToolInfo {
	return &ToolInfo{
		Description:  stringPtr("Search available tools by plain text query or regex pattern and return matching tool definitions."),
		InputSchema:  jsontext.Value([]byte("{\"type\":\"object\",\"properties\":{\"query\":{\"type\":\"string\",\"description\":\"Plain text query matched against tool names, titles, descriptions, metadata, and schemas\"},\"pattern\":{\"type\":\"string\",\"description\":\"Case-insensitive regex pattern matched against tool names, titles, descriptions, metadata, and schemas\"},\"max_results\":{\"type\":\"integer\",\"description\":\"Maximum number of tools to return for this search\"},\"include_schemas\":{\"type\":\"boolean\",\"description\":\"Include input and output schemas in returned descriptors\"},\"category\":{\"type\":\"string\",\"description\":\"Discovery category filter\"},\"tags\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Discovery tag filters\"}},\"additionalProperties\":false}")),
		Name:         name,
		OutputSchema: jsontext.Value([]byte("{\"type\":\"object\",\"required\":[\"tools\",\"total_matches\",\"truncated\"],\"properties\":{\"tools\":{\"type\":\"array\",\"items\":{\"type\":\"object\",\"required\":[\"name\",\"description\"],\"properties\":{\"name\":{\"type\":\"string\"},\"title\":{\"type\":\"string\"},\"description\":{\"type\":\"string\"},\"inputSchema\":{\"type\":\"object\"},\"outputSchema\":{\"type\":\"object\"},\"annotations\":{\"type\":\"object\"},\"_meta\":{\"type\":\"object\"},\"icons\":{\"type\":\"array\",\"items\":{\"type\":\"object\"}},\"category\":{\"type\":\"string\"},\"tags\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"keywords\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"why_matched\":{\"type\":\"array\",\"items\":{\"type\":\"string\"}},\"call_tool_name\":{\"type\":\"string\"},\"call_tool_arguments\":{\"type\":\"object\"},\"call_tool_json\":{\"type\":\"string\"}}}},\"total_matches\":{\"type\":\"integer\"},\"truncated\":{\"type\":\"boolean\"},\"query\":{\"type\":\"string\"},\"pattern\":{\"type\":\"string\"}},\"additionalProperties\":false}")),
		Title:        stringPtr("Search Tools"),
	}
}
func toolCallProxyToolInfo(name string) *ToolInfo {
	return &ToolInfo{
		Description: stringPtr("Call a discovered tool by exact name. Always provide both top-level fields: name and arguments. Use arguments: {} when the discovered tool takes no arguments. Do not use args."),
		InputSchema: jsontext.Value([]byte("{\"type\":\"object\",\"required\":[\"name\",\"arguments\"],\"properties\":{\"name\":{\"type\":\"string\",\"description\":\"Exact discovered tool name. Required. Copy this from search_tools results.\"},\"arguments\":{\"type\":\"object\",\"description\":\"Arguments object for the discovered tool. Required. Use {} when the discovered tool takes no arguments. Do not use args.\"}},\"additionalProperties\":false}")),
		Name:        name,
		Title:       stringPtr("Call Tool"),
	}
}
func toolSearchHaystack(tool *ToolInfo) string {
	if tool == nil {
		return ""
	}
	parts := []string{tool.Name}
	if tool.Description != nil {
		parts = append(parts, *tool.Description)
	}
	if tool.Title != nil {
		parts = append(parts, *tool.Title)
	}
	switch schema := tool.InputSchema.(type) {
	case jsontext.Value:
		parts = append(parts, string(schema))
	case []byte:
		parts = append(parts, string(schema))
	default:
		if schema != nil {
			if raw, err := json.Marshal(schema); err == nil {
				parts = append(parts, string(raw))
			}
		}
	}
	switch schema := tool.OutputSchema.(type) {
	case jsontext.Value:
		parts = append(parts, string(schema))
	case []byte:
		parts = append(parts, string(schema))
	}
	switch meta := tool.Meta.(type) {
	case jsontext.Value:
		parts = append(parts, string(meta))
	case []byte:
		parts = append(parts, string(meta))
	}
	return strings.Join(parts, " ")
}
func toolRawJSON(value any) jsontext.Value {
	switch v := value.(type) {
	case jsontext.Value:
		return v
	case []byte:
		return jsontext.Value(v)
	case string:
		return jsontext.Value([]byte(v))
	default:
		if v == nil {
			return nil
		}
		raw, err := json.Marshal(v)
		if err != nil {
			return nil
		}
		return jsontext.Value(raw)
	}
}
func toolDiscoveryMetadata(tool *ToolInfo) (string, []string, []string) {
	if tool == nil {
		return "", nil, nil
	}
	raw := toolRawJSON(tool.Meta)
	if len(raw) == 0 {
		return "", nil, nil
	}
	var meta map[string]struct {
		Category string   `json:"category"`
		Tags     []string `json:"tags"`
		Keywords []string `json:"keywords"`
	}
	if json.Unmarshal(raw, &meta) != nil {
		return "", nil, nil
	}
	discovery := meta["com.github.caliluke.loom-mcp/discovery"]
	return discovery.Category, discovery.Tags, discovery.Keywords
}
func toolDiscoveryCallTemplateArguments(tool *ToolInfo) map[string]any {
	if tool == nil {
		return nil
	}
	raw := toolRawJSON(tool.Meta)
	if len(raw) == 0 {
		return nil
	}
	var meta map[string]struct {
		CallTemplateArguments map[string]any `json:"call_template_arguments"`
	}
	if json.Unmarshal(raw, &meta) != nil {
		return nil
	}
	discovery := meta["com.github.caliluke.loom-mcp/discovery"]
	if len(discovery.CallTemplateArguments) == 0 {
		return nil
	}
	out := make(map[string]any, len(discovery.CallTemplateArguments))
	for name, value := range discovery.CallTemplateArguments {
		out[name] = value
	}
	return out
}
func toolSearchDescriptorFor(tool *ToolInfo, includeSchemas bool, callName string, query string, score int, settings toolSearchSettings) toolSearchDescriptor {
	category, tags, keywords := toolDiscoveryMetadata(tool)
	callArguments := toolCallArgumentsExample(tool)
	callArgumentsJSON, _ := marshalToolSearchJSON(callArguments)
	descriptor := toolSearchDescriptor{
		CallToolArguments: jsontext.Value(callArgumentsJSON),
		CallToolJSON:      string(callArgumentsJSON),
		CallToolName:      callName,
		Category:          category,
		Keywords:          keywords,
		Name:              tool.Name,
		Tags:              tags,
		WhyMatched:        toolSearchWhyMatched(tool, query, score, settings),
	}
	if tool.Title != nil {
		descriptor.Title = *tool.Title
	}
	if tool.Description != nil {
		descriptor.Description = *tool.Description
	}
	descriptor.Annotations = toolRawJSON(tool.Annotations)
	descriptor.Meta = toolRawJSON(tool.Meta)
	descriptor.Icons = tool.Icons
	if includeSchemas {
		descriptor.InputSchema = toolRawJSON(tool.InputSchema)
		descriptor.OutputSchema = toolRawJSON(tool.OutputSchema)
	}
	return descriptor
}
func toolMatchesCategory(tool *ToolInfo, category string) bool {
	category = strings.TrimSpace(category)
	if category == "" {
		return true
	}
	actual, _, _ := toolDiscoveryMetadata(tool)
	return strings.EqualFold(actual, category)
}
func toolMatchesTags(tool *ToolInfo, required []string) bool {
	if len(required) == 0 {
		return true
	}
	_, tags, _ := toolDiscoveryMetadata(tool)
	available := make(map[string]struct{}, len(tags))
	for _, tag := range tags {
		available[strings.ToLower(strings.TrimSpace(tag))] = struct{}{}
	}
	for _, tag := range required {
		tag = strings.ToLower(strings.TrimSpace(tag))
		if tag == "" {
			continue
		}
		if _, ok := available[tag]; !ok {
			return false
		}
	}
	return true
}
func toolInputParameterText(tool *ToolInfo) string {
	raw := toolRawJSON(tool.InputSchema)
	if len(raw) == 0 {
		return ""
	}
	var schema struct {
		Properties map[string]struct {
			Description string `json:"description"`
		} `json:"properties"`
	}
	if json.Unmarshal(raw, &schema) != nil {
		return ""
	}
	parts := make([]string, 0, len(schema.Properties)*2)
	for name, property := range schema.Properties {
		parts = append(parts, name, property.Description)
	}
	return strings.Join(parts, " ")
}
func toolSearchNormalizeText(text string) string {
	text = strings.ToLower(text)
	replacer := strings.NewReplacer("_", " ", "-", " ", ".", " ", "/", " ", ":", " ", ",", " ", ";", " ", "(", " ", ")", " ", "{", " ", "}", " ", "[", " ", "]", " ", "\"", " ", "'", " ")
	return replacer.Replace(text)
}
func toolSearchToken(token string) string {
	token = strings.TrimSpace(token)
	if len(token) > 3 && strings.HasSuffix(token, "s") {
		token = strings.TrimSuffix(token, "s")
	}
	return token
}
func toolSearchStopWord(token string) bool {
	switch token {
	case "a", "an", "and", "by", "for", "from", "get", "in", "into", "list", "of", "or", "please", "review", "show", "the", "this", "to", "with":
		return true
	default:
		return false
	}
}
func toolSearchTokens(text string) []string {
	fields := strings.Fields(toolSearchNormalizeText(text))
	tokens := make([]string, 0, len(fields))
	for _, field := range fields {
		token := toolSearchToken(field)
		if len(token) <= 1 || toolSearchStopWord(token) {
			continue
		}
		tokens = append(tokens, token)
	}
	return tokens
}
func toolSearchTokenMatch(a string, b string) bool {
	return a == b || strings.HasPrefix(a, b) || strings.HasPrefix(b, a)
}
func toolSearchTokenOverlap(tool *ToolInfo, query string) (int, int) {
	queryTokens := toolSearchTokens(query)
	if len(queryTokens) == 0 {
		return 0, 0
	}
	documentTokens := toolSearchTokens(toolSearchHaystack(tool))
	return toolSearchTokenOverlapForText(queryTokens, documentTokens), len(queryTokens)
}
func toolSearchTokenOverlapForText(queryTokens []string, documentTokens []string) int {
	matched := 0
	for _, queryToken := range queryTokens {
		for _, documentToken := range documentTokens {
			if toolSearchTokenMatch(queryToken, documentToken) {
				matched++
				break
			}
		}
	}
	return matched
}
func toolSearchFuzzyScore(query string, candidates []string) int {
	matches := fuzzy.Find(query, candidates)
	if len(matches) == 0 {
		return 0
	}
	return matches[0].Score
}
func toolSearchWhyMatched(tool *ToolInfo, query string, score int, settings toolSearchSettings) []string {
	query = strings.TrimSpace(query)
	if query == "" || score < 0 {
		return nil
	}
	lowerQuery := strings.ToLower(query)
	normalizedQuery := strings.Join(toolSearchTokens(query), " ")
	name := strings.ToLower(tool.Name)
	normalizedName := strings.Join(toolSearchTokens(tool.Name), " ")
	if name == lowerQuery || normalizedName == normalizedQuery {
		return []string{"exact tool name match"}
	}
	if tool.Title != nil {
		title := strings.ToLower(*tool.Title)
		normalizedTitle := strings.Join(toolSearchTokens(*tool.Title), " ")
		if title == lowerQuery || normalizedTitle == normalizedQuery {
			return []string{"exact title match"}
		}
		if strings.HasPrefix(title, lowerQuery) || strings.HasPrefix(normalizedTitle, normalizedQuery) {
			return []string{"prefix title match"}
		}
	}
	if strings.HasPrefix(name, lowerQuery) || strings.HasPrefix(normalizedName, normalizedQuery) {
		return []string{"prefix tool name match"}
	}
	if settings.fuzzyNameMatching && score >= settings.fuzzyNameWeight*10 {
		return []string{"fuzzy tool name/title match"}
	}
	category, tags, keywords := toolDiscoveryMetadata(tool)
	metadata := category + " " + strings.Join(tags, " ") + " " + strings.Join(keywords, " ")
	queryTokens := toolSearchTokens(query)
	if toolSearchTokenOverlapForText(queryTokens, toolSearchTokens(metadata)) > 0 {
		return []string{"matched discovery metadata token"}
	}
	if tool.Description != nil && toolSearchTokenOverlapForText(queryTokens, toolSearchTokens(*tool.Description)) > 0 {
		return []string{"matched description token"}
	}
	if toolSearchTokenOverlapForText(queryTokens, toolSearchTokens(toolInputParameterText(tool))) > 0 {
		return []string{"matched parameter/schema token"}
	}
	matched, total := toolSearchTokenOverlap(tool, query)
	if total > 0 && matched > 0 {
		return []string{fmt.Sprintf("matched %d of %d query tokens from %q against tool name, title, description, metadata, or parameters", matched, total, query)}
	}
	return []string{fmt.Sprintf("matched query %q against tool metadata", query)}
}
func marshalToolSearchJSON(value any) ([]byte, error) {
	return json.Marshal(value, json.Deterministic(true), jsontext.EscapeForHTML(false), jsontext.WithIndent("  "))
}
func toolExampleValue(property map[string]any) any {
	typ := ""
	switch v := property["type"].(type) {
	case string:
		typ = v
	case []any:
		if len(v) > 0 {
			if s, ok := v[0].(string); ok {
				typ = s
			}
		}
	}
	switch typ {
	case "boolean":
		return false
	case "integer", "number":
		return 0
	case "array":
		return []any{}
	case "object":
		return map[string]any{}
	default:
		return "<string>"
	}
}
func toolCallArgumentsExample(tool *ToolInfo) map[string]any {
	example := map[string]any{
		"arguments": map[string]any{},
		"name":      tool.Name,
	}
	raw := toolRawJSON(tool.InputSchema)
	if len(raw) == 0 {
		return example
	}
	var schema struct {
		Required   []string                  `json:"required"`
		Properties map[string]map[string]any `json:"properties"`
	}
	if json.Unmarshal(raw, &schema) != nil {
		return example
	}
	arguments := map[string]any{}
	for _, name := range schema.Required {
		arguments[name] = toolExampleValue(schema.Properties[name])
	}
	for name, value := range toolDiscoveryCallTemplateArguments(tool) {
		if _, ok := schema.Properties[name]; !ok {
			continue
		}
		arguments[name] = value
	}
	example["arguments"] = arguments
	return example
}
func toolSearchRank(tool *ToolInfo, query string, settings toolSearchSettings) int {
	query = strings.TrimSpace(query)
	if query == "" {
		return 0
	}
	lowerQuery := strings.ToLower(query)
	normalizedQuery := strings.Join(toolSearchTokens(query), " ")
	name := strings.ToLower(tool.Name)
	normalizedName := strings.Join(toolSearchTokens(tool.Name), " ")
	title := ""
	normalizedTitle := ""
	if tool.Title != nil {
		title = strings.ToLower(*tool.Title)
		normalizedTitle = strings.Join(toolSearchTokens(*tool.Title), " ")
	}
	if settings.exactMatchMode != "off" {
		if name == lowerQuery || normalizedName == normalizedQuery {
			return settings.nameWeight * 10
		}
		if title != "" && (title == lowerQuery || normalizedTitle == normalizedQuery) {
			return settings.titleWeight * 10
		}
	}
	if strings.HasPrefix(name, lowerQuery) || strings.HasPrefix(normalizedName, normalizedQuery) {
		return settings.nameWeight * 8
	}
	if title != "" && (strings.HasPrefix(title, lowerQuery) || strings.HasPrefix(normalizedTitle, normalizedQuery)) {
		return settings.titleWeight * 8
	}
	if strings.Contains(name, lowerQuery) || strings.Contains(normalizedName, normalizedQuery) {
		return settings.nameWeight * 7
	}
	if title != "" && (strings.Contains(title, lowerQuery) || strings.Contains(normalizedTitle, normalizedQuery)) {
		return settings.titleWeight * 7
	}
	if settings.fuzzyNameMatching {
		candidates := []string{tool.Name}
		if tool.Title != nil {
			candidates = append(candidates, *tool.Title)
		}
		fuzzyScore := toolSearchFuzzyScore(query, candidates)
		if fuzzyScore > 0 {
			score := settings.fuzzyNameWeight*10 + fuzzyScore
			return score
		}
	}
	if !settings.broadFallback {
		return -1
	}
	category, tags, keywords := toolDiscoveryMetadata(tool)
	metadata := strings.ToLower(category + " " + strings.Join(tags, " ") + " " + strings.Join(keywords, " "))
	if strings.Contains(metadata, lowerQuery) {
		return settings.metadataWeight * 5
	}
	if tool.Description != nil && strings.Contains(strings.ToLower(*tool.Description), lowerQuery) {
		return settings.descriptionWeight * 5
	}
	if strings.Contains(strings.ToLower(toolInputParameterText(tool)), lowerQuery) {
		return settings.parameterWeight * 5
	}
	if strings.Contains(strings.ToLower(toolSearchHaystack(tool)), lowerQuery) {
		return settings.descriptionWeight * 3
	}
	matchedTokens, totalTokens := toolSearchTokenOverlap(tool, query)
	if matchedTokens > 0 && (totalTokens == 1 || matchedTokens > 1) {
		averageBroadWeight := (settings.metadataWeight + settings.descriptionWeight + settings.parameterWeight) / 3
		score := averageBroadWeight * matchedTokens / totalTokens
		if matchedTokens == totalTokens {
			score += averageBroadWeight / 2
		}
		return score
	}
	return -1
}
func (a *MCPAdapter) handleSearchTools(ctx context.Context, p *ToolsCallPayload, stream toolCallStream) (bool, error) {
	var payload toolSearchPayload
	arguments, err := mcpJSONRaw(p.Arguments)
	if err != nil {
		return false, err
	}
	if len(bytes.TrimSpace(arguments)) == 0 {
		arguments = jsontext.Value([]byte("{}"))
	}
	if err := decodeMCPPayloadStrict(arguments, &payload); err != nil {
		return true, a.sendToolError(ctx, stream, p.Name, toolCallError(err, "invalid_params", "Provide {\"query\":\"...\"} or {\"pattern\":\"...\"} to search tools."))
	}
	query := strings.TrimSpace(payload.Query)
	pattern := strings.TrimSpace(payload.Pattern)
	if query != "" && pattern != "" {
		return true, a.sendToolError(ctx, stream, p.Name, toolCallError(loom.PermanentError("invalid_params", "provide query or pattern, not both"), "invalid_params", "Provide either {\"query\":\"...\"} or {\"pattern\":\"...\"}."))
	}
	var re *regexp.Regexp
	if pattern != "" {
		compiled, err := regexp.Compile("(?i)" + pattern)
		if err != nil {
			return true, a.sendToolError(ctx, stream, p.Name, toolCallError(err, "invalid_params", "Provide a valid regular expression pattern."))
		}
		re = compiled
	}
	settings := a.toolSearchSettings()
	limit := settings.maxResults
	if payload.MaxResults != nil && *payload.MaxResults > 0 {
		limit = *payload.MaxResults
	}
	matches := make([]toolSearchCandidate, 0)
	for order, tool := range a.generatedToolCatalog() {
		if tool == nil {
			continue
		}
		if !toolMatchesCategory(tool, payload.Category) {
			continue
		}
		if !toolMatchesTags(tool, payload.Tags) {
			continue
		}
		haystack := toolSearchHaystack(tool)
		matched := query == "" && pattern == ""
		score := 0
		if query != "" {
			score = toolSearchRank(tool, query, settings)
			matched = score >= settings.minScore
		}
		if re != nil {
			matched = re.MatchString(haystack)
		}
		if matched {
			matches = append(matches, toolSearchCandidate{
				order: order,
				score: score,
				tool:  tool,
			})
		}
	}
	sort.SliceStable(matches, func(i int, j int) bool {
		if matches[i].score != matches[j].score {
			return matches[i].score > matches[j].score
		}
		return matches[i].order < matches[j].order
	})
	narrowThreshold := settings.nameWeight * 7
	if titleThreshold := settings.titleWeight * 7; titleThreshold < narrowThreshold {
		narrowThreshold = titleThreshold
	}
	if query != "" && settings.exactMatchMode == "narrow" && len(matches) > 0 && matches[0].score >= narrowThreshold {
		filtered := matches[:0]
		for _, match := range matches {
			if match.score >= narrowThreshold {
				filtered = append(filtered, match)
			}
		}
		matches = filtered
	}
	totalMatches := len(matches)
	truncated := totalMatches > limit
	if truncated {
		matches = matches[:limit]
	}
	descriptors := make([]toolSearchDescriptor, 0, len(matches))
	lines := make([]string, 0, len(matches)+1)
	_, callName := a.toolSearchNames()
	lines = append(lines, fmt.Sprintf("Found %d of %d matching tool(s).", len(matches), totalMatches))
	for _, match := range matches {
		descriptor := toolSearchDescriptorFor(match.tool, payload.IncludeSchemas, callName, query, match.score, settings)
		descriptors = append(descriptors, descriptor)
		lines = append(lines, fmt.Sprintf("Tool: %s", descriptor.Name), fmt.Sprintf("Call this tool through %s. Do not call %s directly.", callName, descriptor.Name), fmt.Sprintf("Tool: %s", callName), "Arguments:", descriptor.CallToolJSON)
	}
	result := &toolSearchResult{
		Pattern:      pattern,
		Query:        query,
		Tools:        descriptors,
		TotalMatches: totalMatches,
		Truncated:    truncated,
	}
	structured, err := json.Marshal(result)
	if err != nil {
		return false, err
	}
	text := strings.Join(lines, "\n")
	return false, stream.SendAndClose(ctx, &ToolsCallResult{
		Content:           []*ContentItem{buildContentItem(a, text)},
		StructuredContent: mcpJSONFromRaw(structured),
	})
}
func (a *MCPAdapter) handleCallToolProxy(ctx context.Context, p *ToolsCallPayload, stream toolCallStream) (bool, error) {
	rawArguments, err := mcpJSONRaw(p.Arguments)
	if err != nil {
		return false, err
	}
	var payload toolCallProxyPayload
	if err := decodeMCPPayloadStrict(rawArguments, &payload); err != nil {
		return true, a.sendToolError(ctx, stream, p.Name, toolCallError(err, "invalid_params", "Provide {\"name\":\"tool_name\",\"arguments\":{...}} to call a discovered tool."))
	}
	payload.Name = strings.TrimSpace(payload.Name)
	if payload.Name == "" {
		return true, a.sendToolError(ctx, stream, p.Name, toolCallError(loom.PermanentError("invalid_params", "Missing required field: name"), "invalid_params", "Provide {\"name\":\"tool_name\",\"arguments\":{...}} to call a discovered tool."))
	}
	if a.isToolSearchName(payload.Name) || a.isToolCallProxyName(payload.Name) {
		return true, a.sendToolError(ctx, stream, p.Name, toolCallError(loom.PermanentError("invalid_params", "call_tool cannot call synthetic tool %q", payload.Name), "invalid_params", "Call one of the real tools returned by search_tools."))
	}
	if !isGeneratedToolName(payload.Name) {
		return true, a.sendToolError(ctx, stream, p.Name, toolCallError(loom.PermanentError("invalid_params", "unknown target tool %q", payload.Name), "invalid_params", "Call one of the real tools returned by search_tools."))
	}
	arguments := payload.Arguments
	if len(bytes.TrimSpace(arguments)) == 0 {
		arguments = jsontext.Value([]byte("{}"))
	}
	proxied := &ToolsCallPayload{
		Arguments: mcpJSONFromRaw(arguments),
		Name:      payload.Name,
	}
	info := a.toolCallInfo(proxied, arguments)
	handler := a.wrapToolCallHandler(info, a.collectRealToolCall)
	result, err := handler(ctx, proxied)
	if err != nil {
		return false, err
	}
	toolErr := result != nil && result.IsError != nil && *result.IsError
	return toolErr, stream.SendAndClose(ctx, result)
}

type StreamChunksStreamBridge struct {
	out     toolCallStream
	adapter *MCPAdapter
}

func (b *StreamChunksStreamBridge) Send(ev *catalog.StreamChunksResult) error {
	return b.SendWithContext(context.Background(), ev)
}
func (b *StreamChunksStreamBridge) SendWithContext(ctx context.Context, ev *catalog.StreamChunksResult) error {
	s, e := mcpruntime.EncodeJSONToString(ctx, goahttp.ResponseEncoder, ev)
	if e != nil {
		return e
	}
	return b.out.Send(ctx, &ToolsCallResult{Content: []*ContentItem{buildContentItem(b.adapter, s)}})
}
func (b *StreamChunksStreamBridge) Close() error {
	return nil
}
func lookupInputRecovery(err error, raw jsontext.Value) string {
	message := strings.TrimSpace(loom.ErrorSafeMessage(err))
	if message == "" {
		message = strings.TrimSpace(err.Error())
	}
	_ = raw
	example := "{\"query\":\"example\"}"
	if field := missingFieldFromMessage(message); field != "" {
		return fmt.Sprintf("Include required field %q. Example: %s", field, example)
	}
	if strings.Contains(message, "unexpected end of JSON input") || strings.Contains(message, "unexpected EOF") {
		return "Provide complete JSON arguments. Example: " + example
	}
	return "Provide valid tool arguments. Example: " + example
}
func projectedLookupInputRecovery(err error, raw jsontext.Value) string {
	message := strings.TrimSpace(loom.ErrorSafeMessage(err))
	if message == "" {
		message = strings.TrimSpace(err.Error())
	}
	_ = raw
	example := "{\"query\":\"example\"}"
	if field := missingFieldFromMessage(message); field != "" {
		return fmt.Sprintf("Include required field %q. Example: %s", field, example)
	}
	if strings.Contains(message, "unexpected end of JSON input") || strings.Contains(message, "unexpected EOF") {
		return "Provide complete JSON arguments. Example: " + example
	}
	return "Provide valid tool arguments. Example: " + example
}
func (a *MCPAdapter) ToolsCall(ctx context.Context, p *ToolsCallPayload) (res *ToolsCallResult, err error) {
	attrs := []attribute.KeyValue{}
	var rawArguments jsontext.Value
	if p != nil {
		rawArguments, err = mcpJSONRaw(p.Arguments)
		if err != nil {
			return nil, err
		}
	}
	if p != nil && p.Name != "" {
		attrs = append(attrs, attribute.String("mcp.tool", p.Name), attribute.String("tool", p.Name))
		if a.isToolCallProxyName(p.Name) {
			var target toolCallProxyPayload
			if json.Unmarshal(rawArguments, &target) == nil && strings.TrimSpace(target.Name) != "" {
				attrs = append(attrs, attribute.String("mcp.target_tool", strings.TrimSpace(target.Name)))
			}
		}
	}
	ctx, span, start, attrs := a.startTelemetry(ctx, "tools/call", attrs...)
	toolErr := false
	defer func() {
		a.finishTelemetry(ctx, span, start, attrs, err, toolErr)
	}()
	info := a.toolCallInfo(p, rawArguments)
	handler := a.wrapToolCallHandler(info, a.collectToolsCall)
	res, err = handler(ctx, p)
	if res != nil && res.IsError != nil {
		toolErr = *res.IsError
	}
	return res, err
}
func (a *MCPAdapter) collectToolsCall(ctx context.Context, p *ToolsCallPayload) (*ToolsCallResult, error) {
	return a.collectToolCall(ctx, p, a.toolsCallHandler)
}
func (a *MCPAdapter) collectRealToolCall(ctx context.Context, p *ToolsCallPayload) (*ToolsCallResult, error) {
	return a.collectToolCall(ctx, p, a.executeRealTool)
}
func (a *MCPAdapter) collectToolCall(ctx context.Context, p *ToolsCallPayload, handler toolCallStreamHandler) (*ToolsCallResult, error) {
	stream := newToolCallResultCollector(a)
	_, err := handler(ctx, p, stream)
	if err != nil {
		return nil, err
	}
	return stream.result(), nil
}
func (a *MCPAdapter) toolsCallHandler(ctx context.Context, p *ToolsCallPayload, stream toolCallStream) (bool, error) {
	if !a.isInitialized(ctx) {
		return false, loom.PermanentError("invalid_params", "Not initialized")
	}
	name := ""
	if p != nil {
		name = p.Name
	}
	a.log(ctx, "request", map[string]any{
		"method": "tools/call",
		"name":   name,
	})
	if a.isToolSearchName(name) {
		return a.handleSearchTools(ctx, p, stream)
	}
	if a.isToolCallProxyName(name) {
		return a.handleCallToolProxy(ctx, p, stream)
	}
	if a.toolSearchEnabled() && !a.opts.ToolSearch.AllowDirectHiddenCalls && isGeneratedToolName(name) && !a.isAlwaysVisibleToolName(name) {
		return false, loom.PermanentError("invalid_params", "Unknown tool: %s", name)
	}
	return a.executeRealTool(ctx, p, stream)
}
func (a *MCPAdapter) executeRealTool(ctx context.Context, p *ToolsCallPayload, stream toolCallStream) (bool, error) {
	arguments, err := mcpJSONRaw(p.Arguments)
	if err != nil {
		return false, err
	}
	arguments = bytes.TrimSpace(arguments)
	if len(arguments) == 0 || bytes.Equal(arguments, []byte("null")) {
		arguments = jsontext.Value([]byte("{}"))
	}
	switch p.Name {
	case "lookup":
		var payload *catalog.LookupPayload
		rawFields, err := decodeMCPPayloadFields(arguments)
		if err != nil {
			return true, a.sendToolError(ctx, stream, p.Name, toolCallError(err, "invalid_params", lookupInputRecovery(err, arguments)))
		}
		if err := decodeMCPPayloadStrict(arguments, &payload); err != nil {
			return true, a.sendToolError(ctx, stream, p.Name, toolCallError(err, "invalid_params", lookupInputRecovery(err, arguments)))
		}
		{
			if err := validateMCPPayloadRequired(rawFields, "query"); err != nil {
				return true, a.sendToolError(ctx, stream, p.Name, toolCallError(err, "invalid_params", lookupInputRecovery(err, arguments)))
			}
		}
		result, err := a.service.Lookup(ctx, payload)
		if err != nil {
			return true, a.sendToolError(ctx, stream, p.Name, err)
		}
		structuredContent, serr := json.Marshal(result)
		if serr != nil {
			return false, serr
		}
		s := string(structuredContent)
		final := &ToolsCallResult{
			Content:           []*ContentItem{buildContentItem(a, s)},
			StructuredContent: mcpJSONFromRaw(structuredContent),
		}
		a.log(ctx, "response", map[string]any{
			"method": "tools/call",
			"name":   p.Name,
		})
		return false, stream.SendAndClose(ctx, final)
	case "stream_chunks":
		bridge := &StreamChunksStreamBridge{
			adapter: a,
			out:     stream,
		}
		if err := a.service.StreamChunks(ctx, bridge); err != nil {
			return true, a.sendToolError(ctx, stream, p.Name, err)
		}
		return false, nil
	case "wait_for_cancel":
		result, err := a.service.WaitForCancel(ctx)
		if err != nil {
			return true, a.sendToolError(ctx, stream, p.Name, err)
		}
		structuredContent, serr := json.Marshal(result)
		if serr != nil {
			return false, serr
		}
		s := string(structuredContent)
		final := &ToolsCallResult{
			Content:           []*ContentItem{buildContentItem(a, s)},
			StructuredContent: mcpJSONFromRaw(structuredContent),
		}
		a.log(ctx, "response", map[string]any{
			"method": "tools/call",
			"name":   p.Name,
		})
		return false, stream.SendAndClose(ctx, final)
	case "projected_lookup":
		args := arguments
		if len(args) == 0 {
			args = jsontext.Value("{}")
		}
		meta := &agentruntime.ToolCallMeta{}
		toolResult, err := projected.DispatchProjectedLookupMethod(ctx, meta, args, nil, projected.ProjectedLookupDispatchOptions{Call: func(ctx context.Context, args any) (any, error) {
			return a.service.ProjectedLookup(ctx, args.(*catalog.ProjectedLookupPayload))
		}})
		if err != nil {
			return true, a.sendToolError(ctx, stream, p.Name, err)
		}
		if toolResult == nil {
			return false, fmt.Errorf("projected tool %q returned nil result", p.Name)
		}
		if toolResult.Error != nil {
			return true, a.sendToolError(ctx, stream, p.Name, toolResult.Error)
		}
		structuredContent, serr := json.Marshal(toolResult.Result)
		if serr != nil {
			return false, serr
		}
		s := string(structuredContent)
		final := &ToolsCallResult{
			Content:           []*ContentItem{buildContentItem(a, s)},
			StructuredContent: mcpJSONFromRaw(structuredContent),
		}
		a.log(ctx, "response", map[string]any{
			"method": "tools/call",
			"name":   p.Name,
		})
		return false, stream.SendAndClose(ctx, final)
	default:
		return false, loom.PermanentError("invalid_params", "Unknown tool: %s", p.Name)
	}
}

// Resources handling
func (a *MCPAdapter) ResourcesRead(ctx context.Context, p *ResourcesReadPayload) (*ResourcesReadResult, error) {
	return sdkbridge.DispatchResource(ctx, p, sdkbridge.ResourceDispatchConfig[*ResourcesReadPayload, *ResourcesReadResult]{
		Initialized:  a.isInitialized,
		Log:          a.log,
		MapError:     a.safeMCPError,
		Policy:       a.resourcePolicy,
		Resources:    a.resourceOperations,
		SkillResult:  nil,
		SkillSources: nil,
		URI: func(payload *ResourcesReadPayload) string {
			if payload == nil {
				return ""
			}
			return payload.URI
		},
	})
}
func (a *MCPAdapter) resourceOperationDescriptors() []sdkbridge.ResourceOperation[*ResourcesReadPayload, *ResourcesReadResult] {
	return []sdkbridge.ResourceOperation[*ResourcesReadPayload, *ResourcesReadResult]{{
		Handle: func(ctx context.Context, request *ResourcesReadPayload, baseURI string) (*ResourcesReadResult, error) {
			args, err := sdkbridge.ResourceQueryJSONTyped(request.URI, map[string]mcpruntime.QueryField{"scope": {String: true}})
			if err != nil {
				return nil, sdkbridge.InvalidClientInput(loom.PermanentError("invalid_params", "Invalid resource request."))
			}
			httpRequest := &http.Request{
				Body:   io.NopCloser(bytes.NewReader(args)),
				Header: http.Header{"Content-Type": []string{"application/json"}},
			}
			var payload *catalog.StatusPayload
			if err := goahttp.RequestDecoder(httpRequest).Decode(&payload); err != nil {
				return nil, sdkbridge.InvalidClientInput(loom.PermanentError("invalid_params", "Invalid resource request."))
			}
			result, err := a.service.Status(ctx, payload)
			if err != nil {
				return nil, err
			}
			text, err := mcpruntime.EncodeJSONToString(ctx, goahttp.ResponseEncoder, result)
			if err != nil {
				return nil, err
			}
			return &ResourcesReadResult{Contents: []*ResourceContent{&ResourceContent{
				MimeType: stringPtr("application/json"),
				Text:     &text,
				URI:      baseURI,
			}}}, nil
		},
		URI: "urn:status",
	}, {
		Handle: func(ctx context.Context, _ *ResourcesReadPayload, baseURI string) (*ResourcesReadResult, error) {
			result, err := a.service.Health(ctx)
			if err != nil {
				return nil, err
			}
			text, err := mcpruntime.EncodeJSONToString(ctx, goahttp.ResponseEncoder, result)
			if err != nil {
				return nil, err
			}
			return &ResourcesReadResult{Contents: []*ResourceContent{&ResourceContent{
				MimeType: stringPtr("application/json"),
				Text:     &text,
				URI:      baseURI,
			}}}, nil
		},
		URI: "urn:health",
	}}
}
